// Extract memory words from an ELF64 (x86-64, little-endian) binary.
// Maps each PT_LOAD segment's bytes onto a 0x400000-based address space and
// emits 4-byte little-endian unsigned integers keyed by address.
'use strict';

const fs = require('fs');

const ELF_MAGIC = 0x7f454c46;
const PT_LOAD = 1;
const BASE = 0x400000n;

function parseElf(buf) {
  if (buf.length < 64 || buf.readUInt32BE(0) !== ELF_MAGIC) {
    throw new Error('Not an ELF file');
  }
  if (buf[4] !== 2) throw new Error('Only 64-bit ELF supported');
  if (buf[5] !== 1) throw new Error('Only little-endian ELF supported');

  const e_phoff = Number(buf.readBigUInt64LE(0x20));
  const e_phentsize = buf.readUInt16LE(0x36);
  const e_phnum = buf.readUInt16LE(0x38);

  const segments = [];
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    if (off + e_phentsize > buf.length) break;
    const p_type = buf.readUInt32LE(off);
    if (p_type !== PT_LOAD) continue;
    segments.push({
      offset: Number(buf.readBigUInt64LE(off + 0x08)),
      vaddr: buf.readBigUInt64LE(off + 0x10),
      filesz: Number(buf.readBigUInt64LE(off + 0x20)),
      memsz: Number(buf.readBigUInt64LE(off + 0x28)),
    });
  }
  return segments;
}

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-binary>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);
  const segments = parseElf(buf);
  const out = {};

  for (const seg of segments) {
    const fileStart = seg.offset;
    const fileEnd = Math.min(seg.offset + seg.filesz, buf.length);
    for (let i = 0; i + 4 <= seg.memsz; i += 4) {
      let value = 0;
      for (let b = 0; b < 4; b++) {
        const idx = i + b;
        let byte = 0;
        if (idx < seg.filesz) {
          const pos = fileStart + idx;
          byte = pos < fileEnd ? buf[pos] : 0;
        }
        value += byte * Math.pow(256, b);
      }
      const addr = (BASE + seg.vaddr + BigInt(i)).toString();
      out[addr] = value >>> 0; // unsigned 32-bit
    }
  }

  process.stdout.write(JSON.stringify(out));
}

main();
