#!/usr/bin/env node
// Extract memory words from an ELF64 little-endian executable.
//
// Address model: each PT_LOAD segment is mapped at 0x400000 + p_vaddr
// (i.e. the classic non-relocated load base) and emitted as 4-byte
// little-endian unsigned integers, keyed by the decimal address.
// Only bytes actually present in the file (p_filesz) are emitted; the
// zero-filled tail (p_memsz > p_filesz, .bss) is skipped.
'use strict';

const fs = require('fs');

const ELF_MAGIC = 0x7f454c46;
const PT_LOAD = 1;
const BASE = 0x400000;

function parseElf(buf) {
  if (buf.length < 64 || buf.readUInt32BE(0) !== ELF_MAGIC) {
    throw new Error('not an ELF file');
  }
  if (buf[4] !== 2) throw new Error('only 64-bit ELF supported');
  if (buf[5] !== 1) throw new Error('only little-endian ELF supported');

  const e_phoff = Number(buf.readBigUInt64LE(0x20));
  const e_phentsize = buf.readUInt16LE(0x36);
  const e_phnum = buf.readUInt16LE(0x38);

  const segs = [];
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    if (off + e_phentsize > buf.length) break;
    if (buf.readUInt32LE(off) !== PT_LOAD) continue;
    segs.push({
      offset: Number(buf.readBigUInt64LE(off + 0x08)),
      vaddr: Number(buf.readBigUInt64LE(off + 0x10)),
      filesz: Number(buf.readBigUInt64LE(off + 0x20)),
    });
  }
  return segs;
}

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-binary>\n');
    process.exit(1);
  }

  const buf = fs.readFileSync(path);
  const out = Object.create(null);

  for (const seg of parseElf(buf)) {
    const avail = Math.min(seg.filesz, buf.length - seg.offset);
    for (let i = 0; i + 4 <= avail; i += 4) {
      const p = seg.offset + i;
      const value = buf.readUInt32LE(p);
      out[String(BASE + seg.vaddr + i)] = value;
    }
  }

  process.stdout.write(JSON.stringify(out));
}

main();
EOF
